/// `Erf` (fixture A with Erf for Abs) runs through `vserf`; the Erf output is
/// within 2 ULP of ORT and the integer branch is exact.
#[test]
fn erf_in_the_graph_against_ort() {
    let reg = registry();
    let (fx, p) = plan("erf", &reg);
    let p = p.unwrap();
    let erf = p.steps.iter().find(|s| s.name == "n_abs").unwrap();
    assert_eq!(erf.key.ordinal, 36);
    let out = p.run(&fx.store, &inputs(None)).unwrap();
    let (shape, got) = f32_bits(&out, "A");
    let (oshape, want) = ort_f32("erf", "A");
    assert_eq!(shape, oshape);
    let worst = got
        .iter()
        .zip(&want)
        .map(|(&a, &b)| ulp(f32::from_bits(a), f32::from_bits(b)))
        .max()
        .unwrap();
    assert!(worst <= 2, "Erf vs ORT: {worst} ULP");
    assert_eq!(outputs(&out).0, ort_out("erf").0);
}

/// Erf over a dense grid of [-6, 6] plus signed zeros, infinities, NaN and
/// subnormals: within 2 ULP of erf in f64 rounded to f32 over [-5, 5] (the
/// ndarray #399 contract), exact on the special values, and the measured
/// distance to ORT pinned.
#[test]
fn erf_sweep_against_f64_and_ort() {
    let o = ort();
    let sw = &o["erf_sweep"];
    let xs: Vec<f32> = u32s(&sw["X_bits"])
        .into_iter()
        .map(f32::from_bits)
        .collect();
    let refs: Vec<f32> = u32s(&sw["f64_ref_bits"])
        .into_iter()
        .map(f32::from_bits)
        .collect();
    let orts: Vec<f32> = u32s(&sw["ort_bits"])
        .into_iter()
        .map(f32::from_bits)
        .collect();
    let b = bytes("erf_sweep");
    let src = SourceInventory::from_bytes(&b).unwrap();
    let facts = tract_facts(&b, &[]).unwrap();
    let g = OnnxGraph::build(&src, &facts).unwrap();
    let reg = registry();
    let store = FrameStore::new(revisions(&src, &reg, &g));
    let p = resolve(&src, g, &reg, &store).unwrap();
    let x = Value::F32(ArrayD::from_shape_vec(IxDyn(&[xs.len()]), xs.clone()).unwrap());
    let out = p.run(&store, &[("X", x)]).unwrap();
    let ys: Vec<f32> = f32_bits(&out, "Y")
        .1
        .into_iter()
        .map(f32::from_bits)
        .collect();
    let (mut in5, mut all, mut vs_ort) = (0u32, 0u32, 0u32);
    for ((&x, &y), (&r, &t)) in xs.iter().zip(&ys).zip(refs.iter().zip(&orts)) {
        let d = ulp(y, r);
        if x.abs() <= 5.0 {
            in5 = in5.max(d);
        }
        all = all.max(d);
        vs_ort = vs_ort.max(ulp(y, t));
        if x == 0.0 || x.is_infinite() || x.is_nan() {
            assert_eq!(y.to_bits(), r.to_bits(), "erf({x:e}) = {y:e}, want {r:e}");
        }
    }
    eprintln!(
        "Erf sweep: {} points, max ULP vs f64 {in5} on [-5,5] ({all} overall), vs ORT {vs_ort}",
        xs.len()
    );
    assert!(in5 <= 2, "{in5} ULP on [-5, 5]");
    assert!(all <= 2, "{all} ULP overall");
    assert!(vs_ort <= 2, "{vs_ort} ULP vs ORT");
}

// ── int64 compares, Where, ConstantOfShape, Expand (registry v3) ────────────

fn ort_ints(v: &str, out: &str) -> (Vec<usize>, Vec<i64>) {
    let e = &ort()["variants"][v]["ort"][out];
    let shape = e["shape"]
        .as_array()
        .unwrap()
        .iter()
        .map(|d| d.as_u64().unwrap() as usize)
        .collect();
    (
        shape,
        e["bits"]
            .as_array()
            .unwrap()
            .iter()
            .map(|b| b.as_i64().unwrap())
            .collect(),
    )
}

fn ints(m: &std::collections::HashMap<String, Value>, k: &str) -> (Vec<usize>, Vec<i64>) {
    match &m[k] {
        Value::I64(a) => (a.shape().to_vec(), a.iter().copied().collect()),
        Value::Bool { shape, words } => (
            shape.clone(),
            (0..shape.iter().product::<usize>())
                .map(|i| ((words[i / 64] >> (i % 64)) & 1) as i64)
                .collect(),
        ),
        other => panic!("{k}: {other:?}"),
    }
}

/// Every int64 node over `Shape(F)` folds through ndarray #400's compares and
/// blends, `from_elem` and `broadcast`; `Expand(F)` reads F and runs. Every
/// output agrees with ORT exactly.
#[test]
fn int64_shape_ops_fold_and_match_ort() {
    let reg = registry();
    let (fx, p) = plan("shape_i64", &reg);
    let p = p.unwrap();
    let folded: Vec<(&str, u16)> = p
        .folded
        .iter()
        .map(|b| (b.name.as_str(), b.key.ordinal))
        .collect();
    assert_eq!(
        folded,
        [
            ("n_shape", 37),
            ("n_equal", 17),
            ("n_where", 19),
            ("n_le", 18),
            ("n_cos", 20),
            ("n_expand_row", 21)
        ]
    );
    let steps: Vec<(&str, u16)> = p
        .steps
        .iter()
        .map(|b| (b.name.as_str(), b.key.ordinal))
        .collect();
    assert_eq!(steps, [("n_expand_f", 22)]);
    let out = p.run(&fx.store, &[("F", f_input())]).unwrap();
    for k in ["W", "LE", "CS", "ER"] {
        assert_eq!(ints(&out, k), ort_ints("shape_i64", k), "{k}");
    }
    assert_eq!(f32_bits(&out, "EF"), ort_f32("shape_i64", "EF"));
}

/// An omitted optional output before a present one (`LSTM` outputs
/// `["", "Y_h"]`): Tract numbers outlets after dropping empty names, so
/// `Y_h` is slot 0, not 1. `source_producers` must name that outlet, and the
/// fact admitted for `Y_h` must be `Y_h`'s (ORT's shape `[1, 1, 2]`), not the
/// omitted `Y`'s (`[5, 1, 1, 2]`). With both outputs present `Y_h` is slot 1.
#[test]
fn an_omitted_optional_output_does_not_shift_the_producer() {
    use tract_harvest_probe::dr3::{source_producers, tract_fact_sources, Outlet};
    use tract_harvest_probe::registry::{Dim, Fact};
    let dims = |s: &[usize]| Some(s.iter().map(|&d| Dim::Known(d)).collect::<Vec<_>>());
    for (v, slot) in [("lstm_skip", 0), ("lstm_full", 1)] {
        let b = bytes(v);
        let src = SourceInventory::from_bytes(&b).unwrap();
        let p = source_producers(&src);
        assert_eq!(
            p["Y_h"],
            Some(Outlet {
                node: "n_lstm".into(),
                slot
            }),
            "{v}"
        );
        let (shape, _) = ort_f32(v, "Y_h");
        assert_eq!(shape, [1, 1, 2]);
        let fs = tract_fact_sources(&b, &[]).unwrap();
        assert_eq!(
            fs.inference.get("Y_h"),
            Some(&Fact {
                dtype: Some(tract_harvest_probe::value::DType::F32),
                shape: dims(&shape)
            }),
            "{v}"
        );
    }
    let fs = tract_fact_sources(&bytes("lstm_full"), &[]).unwrap();
    assert_eq!(
        fs.inference["Y"].shape,
        dims(&[5, 1, 1, 2]),
        "the other output's shape differs"
    );
}

/// The whole int64 shape-arithmetic chain (Shape → Div/Mul/Add/Sub,
/// Gather → Range) folds through admitted methods on
/// `ndarray::hpc::checked_i64` and matches ORT exactly. Div truncates toward
/// zero (`-7 / 2 = -3`).
#[test]
fn int64_arithmetic_folds_and_matches_ort() {
    let reg = registry();
    let (fx, p) = plan("i64_arith", &reg);
    let p = p.unwrap();
    let folded: Vec<(&str, u16)> = p
        .folded
        .iter()
        .map(|b| (b.name.as_str(), b.key.ordinal))
        .collect();
    assert_eq!(
        folded,
        [
            ("n_shape", 37),
            ("n_div", 26),
            ("n_mul", 25),
            ("n_add", 23),
            ("n_sub", 24),
            ("n_gather", 41),
            ("n_range", 27)
        ]
    );
    assert!(p.steps.is_empty(), "{:?}", p.steps);
    let out = p.run(&fx.store, &[("F", f_input())]).unwrap();
    for k in ["DV", "ML", "AD", "SB", "RG"] {
        assert_eq!(ints(&out, k), ort_ints("i64_arith", k), "{k}");
    }
    assert_eq!(ints(&out, "DV").1, [-3, 2], "Div truncates toward zero");
}

/// An initializer whose fact the frontend did not admit (on Jina, `_one` is
/// carried by two Tract outlets and rejected) still has the source's own
/// dtype and dims: `Range` folds without the fact. A refused fold leaves no
/// value behind: the overflowing node's output is never written.
#[test]
fn source_declared_initializer_facts_and_refusal_leave_no_output() {
    use tract_harvest_probe::fold::fold;
    let reg = registry();
    let src = SourceInventory::from_bytes(&bytes("i64_arith")).unwrap();
    let mut facts = tract_facts(&bytes("i64_arith"), &[]).unwrap();
    facts.remove("r0");
    facts.remove("r1");
    assert!(!facts.contains_key("r0") && !facts.contains_key("r1"));
    let f = fold(&src, &facts, &reg);
    let rg = src.nodes.iter().position(|n| n.name == "n_range").unwrap();
    assert!(f.nodes.contains(&rg), "{:?}", f.blocked);
    assert!(f.refused.is_empty());

    let src = SourceInventory::from_bytes(&bytes("neg_i64_overflow")).unwrap();
    let facts = tract_facts(&bytes("neg_i64_overflow"), &[]).unwrap();
    let f = fold(&src, &facts, &reg);
    let bad = src.nodes.iter().position(|n| n.name == "n_bad").unwrap();
    assert_eq!(f.refused.iter().map(|(n, _)| *n).collect::<Vec<_>>(), [bad]);
    assert!(!f.nodes.contains(&bad));
    assert!(!f.values.contains_key("Y"), "a refused node writes nothing");
    assert!(f.values.contains_key("s"), "its producer still folded");
}

/// int64 arithmetic on a run-time input stays a step and runs per run; a run
/// whose values overflow refuses (ORT wraps: `neg_i64_overflow` records
/// `i64::MIN` for `2 * 2^62`).
#[test]
fn int64_arithmetic_on_data_runs_and_refuses_overflow() {
    let reg = registry();
    let (fx, p) = plan("i64_data", &reg);
    let p = p.unwrap();
    let steps: Vec<(&str, u16)> = p
        .steps
        .iter()
        .map(|b| (b.name.as_str(), b.key.ordinal))
        .collect();
    assert_eq!(steps, [("n_mul", 25)]);
    let i = |v: Vec<i64>| Value::I64(ArrayD::from_shape_vec(IxDyn(&[2]), v).unwrap());
    let out = p
        .run(&fx.store, &[("F", f_input()), ("I", i(vec![-4, 5]))])
        .unwrap();
    assert_eq!(ints(&out, "MI"), ort_ints("i64_data", "MI"));
    match p.run(&fx.store, &[("F", f_input()), ("I", i(vec![i64::MAX, 1]))]) {
        Err(Refusal::Runtime { node, what }) => {
            assert_eq!(node, "n_mul");
            assert!(what.contains("verflow"), "{what}");
        }
        other => panic!("{:?}", other.map(|_| ())),
    }
}

/// Invalid constant arithmetic refuses the plan instead of leaving the node
/// unfolded: overflow (ORT wraps it) and a broadcast this registration does
/// not admit (`[2]` against `[2, 1]`). A zero divisor (undefined in ORT) and a
/// zero Range step (ORT refuses too) are already refused by Tract's analysis.
#[test]
fn invalid_int64_arithmetic_refuses() {
    let reg = registry();
    assert_eq!(
        ort()["variants"]["neg_i64_overflow"]["ort"]["Y"]["bits"],
        serde_json::json!([i64::MIN, 3]),
        "ORT wraps on overflow"
    );
    // Tract's own analysis evaluates the constant Div and refuses the zero
    // divisor before our fold runs; the registry DO refuses it too
    // (`checked_i64_dos_refuse`).
    // A zero Range step makes Tract's dimension arithmetic panic; `no_panic`
    // turns that into a frontend refusal.
    for (v, want) in [
        ("neg_i64_div0", "Division by zero"),
        ("neg_range_zero", "divide by zero"),
    ] {
        match tract_facts(&bytes(v), &[]) {
            Err(Refusal::Frontend(e)) => assert!(e.contains(want), "{v}: {e}"),
            other => panic!("{v}: {:?}", other.map(|f| f.len())),
        }
    }
    match plan("neg_i64_overflow", &reg).1 {
        Err(Refusal::Runtime { node, what }) => {
            assert_eq!(node, "n_bad");
            assert!(what.contains("overflows"), "{what}");
        }
        other => panic!("{:?}", other.map(|_| ())),
    }
    {
        let (v, ordinal) = ("neg_i64_bcast", 23);
        match plan(v, &reg).1 {
            Err(Refusal::When {
                node, key, truth, ..
            }) => {
                assert_eq!(
                    (node.as_str(), key.ordinal, truth),
                    ("n_bad", ordinal, K3::False),
                    "{v}"
                );
            }
            other => panic!("{v}: {:?}", other.map(|_| ())),
        }
    }
}

/// The Jina rotary-embedding and causal-mask structure (self-authored
/// fixture `rope`): positions come from the input's shape, so at a fixed
/// shape every node folds, including Cast i64 -> f32, MatMul, Transpose, an
/// f32 Concat, Cos, Sin, a broadcast LessOrEqual, Cast bool and And. The
/// mask matches ORT exactly; Cos and Sin are compared bit for bit and the
/// largest ULP distance is pinned.
#[test]
fn rotary_chain_folds_and_matches_ort() {
    let reg = registry();
    let (fx, p) = plan("rope", &reg);
    let p = p.unwrap();
    assert!(
        p.steps.is_empty(),
        "{:?}",
        p.steps.iter().map(|b| &b.name).collect::<Vec<_>>()
    );
    let folded: Vec<u16> = p.folded.iter().map(|b| b.key.ordinal).collect();
    for c in [28, 29, 30, 31, 33, 34, 35, 18] {
        assert!(folded.contains(&c), "item {c} did not fold");
    }
    let ids = Value::I64(ArrayD::from_shape_vec(IxDyn(&[1, 10]), (0..10).collect()).unwrap());
    let out = p.run(&fx.store, &[("ids", ids)]).unwrap();
    assert_eq!(ints(&out, "MASK"), ort_ints("rope", "MASK"));
    let mask = ints(&out, "MASK").1;
    assert_eq!(mask.iter().sum::<i64>(), 55, "lower triangle of 10 x 10");
    let mut worst = 0;
    for k in ["COS", "SIN"] {
        let (shape, got) = f32_bits(&out, k);
        let (want_shape, want) = ort_f32("rope", k);
        assert_eq!(shape, want_shape, "{k}");
        let d = got
            .iter()
            .zip(&want)
            .map(|(&g, &w)| ulp(f32::from_bits(g), f32::from_bits(w)))
            .max()
            .unwrap();
        eprintln!("rope {k}: max ULP vs ORT {d}");
        worst = worst.max(d);
    }
    assert!(worst <= 1, "{worst} ULP");
}

/// f32 MatMul with K > 1, against a weight and attention-shaped: sgemm's
/// accumulation order differs from ORT's, so the distance is measured and
/// pinned, not assumed zero.
#[test]
fn matmul_f32_against_ort() {
    let o = ort();
    let ins = &o["variants"]["matmul"]["inputs"];
    let input = |k: &'static str| {
        let shape: Vec<usize> = ins[k]["shape"]
            .as_array()
            .unwrap()
            .iter()
            .map(|d| d.as_u64().unwrap() as usize)
            .collect();
        (k, f32_value(&shape, &u32s(&ins[k]["bits"])))
    };
    let reg = registry();
    let (fx, p) = plan("matmul", &reg);
    let p = p.unwrap();
    let steps: Vec<(&str, u16)> = p
        .steps
        .iter()
        .map(|b| (b.name.as_str(), b.key.ordinal))
        .collect();
    assert_eq!(steps, [("n_mm_weight", 30), ("n_mm_attn", 30)]);
    let out = p
        .run(&fx.store, &[input("A"), input("Q"), input("K")])
        .unwrap();
    let mut worst = 0;
    for k in ["Y1", "Y2"] {
        let (shape, got) = f32_bits(&out, k);
        let (want_shape, want) = ort_f32("matmul", k);
        assert_eq!(shape, want_shape, "{k}");
        let d = got
            .iter()
            .zip(&want)
            .map(|(&g, &w)| ulp(f32::from_bits(g), f32::from_bits(w)))
            .max()
            .unwrap();
        eprintln!("matmul {k}: max ULP vs ORT {d}");
        worst = worst.max(d);
    }
    // Measured 0 ULP on this host; sgemm may pick another kernel elsewhere.
    assert!(worst <= 2, "{worst} ULP");
}

/// Cos and Sin (`vscos` / `vssin`) over rotary angles (position x inv_freq up
/// to 8192), a dense grid of [-4 pi, 4 pi] and special values: distance to
/// ORT and to f64 rounded once to f32, measured and pinned (at most 1 ULP
/// from f64, at most 2 from ORT, which is itself 2 from f64); NaN for
/// infinities and NaN.
#[test]
fn trig_sweep_against_f64_and_ort() {
    let o = ort();
    let sw = &o["trig_sweep"];
    let f = |k: &str| -> Vec<f32> { u32s(&sw[k]).into_iter().map(f32::from_bits).collect() };
    let xs = f("X_bits");
    let b = bytes("trig_sweep");
    let src = SourceInventory::from_bytes(&b).unwrap();
    let facts = tract_facts(&b, &[]).unwrap();
    let g = OnnxGraph::build(&src, &facts).unwrap();
    let reg = registry();
    let store = FrameStore::new(revisions(&src, &reg, &g));
    let p = resolve(&src, g, &reg, &store).unwrap();
    let x = Value::F32(ArrayD::from_shape_vec(IxDyn(&[xs.len()]), xs.clone()).unwrap());
    let out = p.run(&store, &[("X", x)]).unwrap();
    for (k, ort_k, ref_k) in [
        ("C", "ort_cos_bits", "f64_cos_bits"),
        ("S", "ort_sin_bits", "f64_sin_bits"),
    ] {
        let ys: Vec<f32> = f32_bits(&out, k)
            .1
            .into_iter()
            .map(f32::from_bits)
            .collect();
        let (orts, refs) = (f(ort_k), f(ref_k));
        let (mut vs_ref, mut vs_ort, mut ort_vs_ref) = (0u32, 0u32, 0u32);
        for (((&x, &y), &t), &r) in xs.iter().zip(&ys).zip(&orts).zip(&refs) {
            if x.is_finite() {
                vs_ref = vs_ref.max(ulp(y, r));
                ort_vs_ref = ort_vs_ref.max(ulp(t, r));
            } else {
                assert!(y.is_nan() && t.is_nan(), "{k}({x}) = {y}, ORT {t}");
            }
            vs_ort = vs_ort.max(ulp(y, t));
        }
        eprintln!(
            "{k} sweep: {} points, max ULP vs f64 {vs_ref}, vs ORT {vs_ort} (ORT vs f64 {ort_vs_ref})",
            xs.len()
        );
        // vscos/vssin round per lane through libm f32 and stay within 1 ULP
        // of f64; ORT itself is 2 ULP from f64 on this sweep, which is the
        // whole of the measured distance to ORT.
        assert!(vs_ref <= 1, "{k}: {vs_ref} ULP vs f64");
        assert!(vs_ort <= 2, "{k}: {vs_ort} ULP vs ORT");
    }
}

/// External-data Constants are inlined only from a manifest whose digest,
/// length and dtype match, and only into an undecoded Constant.
#[test]
fn external_constants_inline_only_when_pinned() {
    use tract_harvest_probe::source::{sha256_hex, Attr, SourceNode};
    let (mut src, g) = graph("base");
    let reg = registry();
    src.nodes.push(SourceNode {
        name: "c_ext".into(),
        op_type: "Constant".into(),
        domain: String::new(),
        inputs: vec![],
        outputs: vec!["ext_out".into()],
        attributes: vec!["value".into()],
        attrs: vec![("value".into(), Attr::Tensor(None))],
    });
    let dir = std::env::temp_dir().join(format!("tract-ext-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let data: Vec<u8> = [1.5f32, -2.0]
        .iter()
        .flat_map(|v| v.to_le_bytes())
        .collect();
    std::fs::write(dir.join("c.bin"), &data).unwrap();
    let manifest = |sha: &str, dims: &str| {
        let p = dir.join("m.json");
        std::fs::write(
            &p,
            format!(r#"{{"constants":[{{"output":"ext_out","dtype":"f32","dims":{dims},"sha256":"{sha}","file":"c.bin"}}]}}"#),
        )
        .unwrap();
        p
    };
    let good = sha256_hex(&data);
    let first = src.nodes[0].outputs[0].clone();
    let e = src
        .inline_external_constant(&first, Value::F32(ArrayD::zeros(IxDyn(&[1]))))
        .unwrap_err();
    assert!(e.contains("exactly one Constant"), "{e}");
    let e = src
        .inline_constants_from_manifest(&manifest(&"0".repeat(64), "[2]"), &dir)
        .unwrap_err();
    assert!(e.contains("sha256"), "{e}");
    let e = src
        .inline_constants_from_manifest(&manifest(&good, "[3]"), &dir)
        .unwrap_err();
    assert!(e.contains("bytes"), "{e}");
    let pristine = src.clone();
    assert_eq!(
        src.inline_constants_from_manifest(&manifest(&good, "[2]"), &dir),
        Ok(1)
    );
    // The inlined bytes are not in `model_sha256`, so the source revision has
    // to carry them: another value inlined into the same model is another
    // source.
    let mut other = pristine.clone();
    other
        .inline_external_constant(
            "ext_out",
            Value::F32(ArrayD::from_shape_vec(IxDyn(&[2]), vec![1.5, -2.5]).unwrap()),
        )
        .unwrap();
    let rev = |s: &SourceInventory| revisions(s, &reg, &g).source;
    assert_eq!(src.model_sha256, other.model_sha256);
    assert_ne!(rev(&src), rev(&pristine));
    assert_ne!(rev(&src), rev(&other));
    match src.nodes.last().unwrap().attr("value") {
        Some(Attr::Tensor(Some(Value::F32(a)))) => {
            assert_eq!(a.iter().copied().collect::<Vec<_>>(), [1.5, -2.0])
        }
        other => panic!("{other:?}"),
    }
    let e = src
        .inline_constants_from_manifest(&manifest(&good, "[2]"), &dir)
        .unwrap_err();
    assert!(e.contains("already decoded"), "{e}");
    std::fs::remove_dir_all(&dir).unwrap();
}

/// Facts read from one model refuse to bind to another (a stale binding):
/// `gen2` has `base`'s value names but different bytes.
#[test]
fn facts_of_another_model_refuse_to_bind() {
    use tract_harvest_probe::dr3::tract_fact_sources;
    let base = SourceInventory::from_bytes(&bytes("base")).unwrap();
    let gen2 = tract_fact_sources(&bytes("gen2"), &[]).unwrap();
    match gen2.merged_for(&base) {
        Err(Refusal::Frontend(e)) => assert!(e.contains("applied to model"), "{e}"),
        other => panic!("{:?}", other.map(|m| m.len())),
    }
    let own = tract_fact_sources(&bytes("base"), &[]).unwrap();
    assert!(own.merged_for(&base).is_ok());
}

/// A classid is a codebook lens: every item is read through the one ONNX
/// lens, its ordinal is its position, and another lens reads nothing here.
#[test]
fn one_lens_many_items() {
    use tract_harvest_probe::registry::{MethodKey, ONNX_LENS};
    let reg = registry();
    assert_eq!(reg.lens, ONNX_LENS);
    assert!(reg.regs.len() > 1);
    for (i, r) in reg.regs.iter().enumerate() {
        let key = reg.key_of(r);
        assert_eq!(
            key,
            MethodKey {
                lens: ONNX_LENS,
                ordinal: i as u16
            }
        );
        assert!(std::ptr::eq(reg.get(key).unwrap(), r));
        let foreign = MethodKey {
            lens: ONNX_LENS + 1,
            ..key
        };
        assert!(reg.get(foreign).is_none());
    }
}

const BIND_VARIANTS: &[&str] = &[
    "base",
    "div3",
    "erf",
    "erf_sweep",
    "gen2",
    "i64_arith",
    "i64_data",
    "lstm_full",
    "lstm_skip",
    "matmul",
    "rope",
    "shape_fold",
    "shape_i64",
    "shape_sym",
    "trig_sweep",
];

/// The ONNX registry splits into a route (position → (lens, ordinal), by
/// signature, once) and a bind-store resolve (lens → item) that gives back
/// exactly what the one-step signature lookup gives, for every node of every
/// fixture. An unregistered node has no route and resolves as `Route`.
#[test]
fn route_then_resolve_equals_signature_lookup() {
    use tract_harvest_probe::bind::{resolve, route, Unresolved};
    let reg = registry();
    let (mut routed, mut unrouted) = (0, 0);
    for v in BIND_VARIANTS {
        let b = bytes(v);
        let src = SourceInventory::from_bytes(&b).unwrap();
        let facts =
            tract_harvest_probe::fold::with_initializer_facts(&src, &tract_facts(&b, &[]).unwrap());
        let routes = route(&src, &facts, &reg);
        for (n, node) in src.nodes.iter().enumerate() {
            let args: Vec<_> = node.inputs.iter().map(|i| facts.get(i)).collect();
            match (reg.lookup(node, &args), resolve(&routes, &reg, n)) {
                (Some(a), Ok(b)) => {
                    assert!(std::ptr::eq(a, b), "{v} node {n}");
                    routed += 1;
                }
                (None, Err(Unresolved::Route { node })) => {
                    assert_eq!(node, n);
                    unrouted += 1;
                }
                (a, b) => panic!(
                    "{v} node {n}: lookup {:?} vs resolve {:?}",
                    a.map(|r| r.method),
                    b.map(|r| r.method)
                ),
            }
        }
    }
    assert!(
        routed > 50 && unrouted > 0,
        "routed {routed}, unrouted {unrouted}"
    );
}

/// A route read through another lens, or to an ordinal the lens does not
/// hold, names its failed link; a different registry (or any re-route) is a
/// different route version.
#[test]
fn bind_store_names_the_failed_link_and_versions_routes() {
    use tract_harvest_probe::bind::{resolve, route, Unresolved};
    let reg = registry();
    let b = bytes("rope");
    let src = SourceInventory::from_bytes(&b).unwrap();
    let facts = tract_facts(&b, &[]).unwrap();
    let routes = route(&src, &facts, &reg);
    let (&n, &key) = routes.map.iter().next_back().unwrap();
    let mut foreign = routes.clone();
    foreign.map.get_mut(&n).unwrap().lens += 1;
    assert_eq!(
        resolve(&foreign, &reg, n).map(|r| r.method),
        Err(Unresolved::Lens {
            node: n,
            lens: key.lens + 1
        })
    );
    // A shorter table does not hold the item at this ordinal.
    let mut shorter = registry();
    shorter.regs.truncate(usize::from(key.ordinal));
    assert_eq!(
        resolve(&routes, &shorter, n).map(|r| r.method),
        Err(Unresolved::Item { node: n, key })
    );
    // Re-routing against it drops that node's route and moves the version.
    let rerouted = route(&src, &facts, &shorter);
    assert!(!rerouted.map.contains_key(&n));
    assert_ne!(rerouted.version, routes.version);
    // Same routes, other registry version: another version too.
    let mut bumped = registry();
    bumped.version += 1;
    assert_ne!(route(&src, &facts, &bumped).version, routes.version);
    assert_eq!(route(&src, &facts, &reg), routes);
}

/// The ERB field-view split: algebra addresses are lens-agnostic positions,
/// the lens's fields label them, and several fields may label one address.
#[test]
fn fields_label_shared_algebra_addresses() {
    let reg = registry();
    assert_eq!(reg.regs.len(), 48);
    assert!(reg.methods.len() < reg.regs.len(), "{}", reg.methods.len());
    for r in &reg.regs {
        assert!(usize::from(r.method) < reg.methods.len());
    }
    let constants: Vec<u16> = reg
        .regs
        .iter()
        .filter(|r| r.op_type == "Constant")
        .map(|r| r.method)
        .collect();
    assert_eq!(constants.len(), 3);
    assert!(constants.iter().all(|&m| m == constants[0]));
    // Every address is labelled by some field: none is dead.
    for m in 0..reg.methods.len() {
        assert!(reg.regs.iter().any(|r| usize::from(r.method) == m), "{m}");
    }
}

/// A field outside the lens's mask is absent: it neither matches nor
/// resolves, its node is UNREGISTERED, and the revision moves. The other
/// fields still read the shared algebra address it labelled.
#[test]
fn a_masked_field_is_absent() {
    use tract_harvest_probe::bind::{resolve, route, Unresolved};
    let reg = registry();
    let b = bytes("rope");
    let src = SourceInventory::from_bytes(&b).unwrap();
    let facts = tract_facts(&b, &[]).unwrap();
    let routes = route(&src, &facts, &reg);
    let (&n, &key) = routes.map.iter().next_back().unwrap();
    let hidden = usize::from(key.ordinal);
    let mut masked = registry();
    masked.expose(hidden, false);
    assert!(!masked.exposes(hidden) && masked.exposes(0));
    assert!(masked.get(key).is_none());
    assert_eq!(
        resolve(&routes, &masked, n).map(|r| r.method),
        Err(Unresolved::Item { node: n, key })
    );
    let node = &src.nodes[n];
    let args: Vec<_> = node.inputs.iter().map(|i| facts.get(i)).collect();
    assert!(reg.lookup(node, &args).is_some());
    assert!(masked.lookup(node, &args).is_none());
    assert!(!route(&src, &facts, &masked).map.contains_key(&n));
    assert_ne!(masked.revision(), reg.revision());
    assert_eq!(masked.version, reg.version);
    // Every route to another field still resolves, to the same ordinal.
    for (&m, &k) in routes.map.iter().filter(|(_, k)| k.ordinal != key.ordinal) {
        let r = resolve(&routes, &masked, m).unwrap();
        assert_eq!(masked.key_of(r), k);
    }
}

fn jina_input(k: &'static str) -> (&'static str, Value) {
    let o = ort();
    let e = &o["variants"]["jina_ops"]["inputs"][k];
    let shape: Vec<usize> = e["shape"]
        .as_array()
        .unwrap()
        .iter()
        .map(|d| d.as_u64().unwrap() as usize)
        .collect();
    let bits = e["bits"].as_array().unwrap();
    let v = match e["dtype"].as_str().unwrap() {
        "float32" => f32_value(&shape, &u32s(&e["bits"])),
        "int64" => Value::I64(
            ndarray::ArrayD::from_shape_vec(
                ndarray::IxDyn(&shape),
                bits.iter().map(|b| b.as_i64().unwrap()).collect(),
            )
            .unwrap(),
        ),
        "bool" => {
            let mut words = vec![0u64; bits.len().div_ceil(64)];
            for (i, b) in bits.iter().enumerate() {
                if b.as_i64().unwrap() != 0 {
                    words[i / 64] |= 1 << (i % 64);
                }
            }
            Value::Bool { shape, words }
        }
        d => panic!("{k}: {d}"),
    };
    (k, v)
}

/// Jina's 14 unregistered op types, one node per shape pattern
/// (`tools/gen_tiny.py` `jina_ops`), resolved and run node by node against
/// ORT (`ORT_DISABLE_ALL`). Exact ops agree bit for bit; Sigmoid and Softmax
/// are bounded and reported in ULP.
#[test]
fn jina_ops_against_ort() {
    let reg = registry();
    let (fx, p) = plan("jina_ops", &reg);
    let p = p.unwrap_or_else(|e| panic!("{e:?}"));
    let ins: Vec<_> = [
        "X", "M", "C", "Y", "NAN_IN", "SM_IN", "SG_IN", "CI", "RI", "BE", "GE",
    ]
    .into_iter()
    .map(jina_input)
    .collect();
    let out = p.run(&fx.store, &ins).unwrap();
    let f32_outs = [
        ("slice_hi", 0),
        ("slice_lo", 0),
        ("neg", 0),
        ("where_a", 0),
        ("where_b", 0),
        ("gather_f", 0),
        ("gather_el", 0),
        ("squeeze", 0),
        ("sigmoid", 4),
        ("softmax", 4),
    ];
    for (k, bound) in f32_outs {
        let (shape, got) = f32_bits(&out, k);
        let (want_shape, want) = ort_f32("jina_ops", k);
        assert_eq!(shape, want_shape, "{k}");
        let d = got
            .iter()
            .zip(&want)
            .map(|(&g, &w)| ulp(f32::from_bits(g), f32::from_bits(w)))
            .max()
            .unwrap();
        if bound == 0 {
            eprintln!("jina_ops {k}: max ULP vs ORT {d}");
            assert_eq!(d, 0, "{k}");
            continue;
        }
        // Bounded ops: the reference is f64 over the same input; ORT is
        // reported, not asserted (its sigmoid flushes sigmoid(-20) = 2.06e-9
        // to 0, which is 8e8 ULP from the true value).
        let input = |name: &str| match &ins.iter().find(|(n, _)| *n == name).unwrap().1 {
            Value::F32(a) => a.iter().map(|&v| v as f64).collect::<Vec<f64>>(),
            _ => unreachable!(),
        };
        let reference: Vec<f64> = if k == "sigmoid" {
            input("SG_IN")
                .iter()
                .map(|x| 1.0 / (1.0 + (-x).exp()))
                .collect()
        } else {
            input("SM_IN")
                .chunks(3)
                .flat_map(|row| {
                    let m = row.iter().cloned().fold(f64::MIN, f64::max);
                    let e: Vec<f64> = row.iter().map(|x| (x - m).exp()).collect();
                    let s: f64 = e.iter().sum();
                    e.into_iter().map(move |v| v / s)
                })
                .collect()
        };
        let vs_f64 = got
            .iter()
            .zip(&reference)
            .map(|(&g, &r)| ulp(f32::from_bits(g), r as f32))
            .max()
            .unwrap();
        eprintln!("jina_ops {k}: max ULP vs f64 {vs_f64}, vs ORT {d}");
        assert!(vs_f64 <= bound, "{k}: {vs_f64} ULP from f64 > {bound}");
    }
    for k in [
        "slice_bool",
        "isnan",
        "cast_bool",
        "flatten_b",
        "gather_b",
        "reshape_b1",
        "reshape_b2",
        "expand_b",
        "reduce_i64",
    ] {
        assert_eq!(ints(&out, k), ort_ints("jina_ops", k), "{k}");
    }
    // The isnan output is not vacuous: the input carries NaN and ±inf.
    let (_, isnan) = ints(&out, "isnan");
    assert_eq!(isnan.iter().filter(|&&b| b == 1).count(), 2);
}
